{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Santa Ana Rent Stabilization Ordinance annual rent cap","requirement":"A landlord may not raise residential rent by more than the lower of 3% per year or 80% of the change in the Consumer Price Index over the most recent 12-month period; if CPI is negative, no increase is permitted.","key_value":"lower of 3% per year or 80% of CPI over 12 months","coverage_conditions":"Residential rental units, but the cap does not apply to buildings constructed after February 1, 1995, or to mobile home spaces offered for rent after January 1, 1990.","applicability":{"built_on_or_before":"1995-02-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":"Mobile home spaces offered for rent after January 1, 1990 are outside the cap; owners may petition for relief from the cap"},"exemptions":"Residential buildings constructed after February 1, 1995; mobile home spaces offered for rent after January 1, 1990.","penalty":null,"effective_date":"2021-11-19","citation":"Santa Ana Rent Stabilization Ordinance","quoted_span":"Increase in residential rents are limited to the lower of 3% per year, or 80% of the percent change in the Consumer Price Index over the most recent 12-month period. If the CPI is negative, no rent increase is permitted.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Santa Ana Just Cause Eviction Ordinance","requirement":"After 30 days a landlord may not terminate a tenancy without just cause stated in a written notice, and must first give notice and time to cure; no-fault terminations require 3 months' relocation assistance or a waiver of the final 3 months' rent.","key_value":"3 months' relocation assistance or 3 months' rent waiver","coverage_conditions":"Tenancies of 30 days or more; exempts housing produced in the last 15 years, deed-restricted affordable housing, hotel and transient occupancy, hospital and care facilities, dormitories and other shared living quarters.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Exempts housing produced in the last 15 years, deed-restricted affordable housing, hotels and transient occupancy, hospitals and care facilities, dormitories and other shared living quarters"},"exemptions":"Housing produced in the last 15 years; deed-restricted affordable housing; hotel and transient occupancy; hospital and care facilities; dormitories; other shared living quarters.","penalty":null,"effective_date":"2021-11-19","citation":"Santa Ana Just Cause Eviction Ordinance","quoted_span":"After 30 days, an owner shall not terminate a tenancy without just cause, which shall be stated in a written notice.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
